package com.habilitesrandom.transformation;
import com.habilitesrandom.data.*;import com.habilitesrandom.core.CoreServices;import com.habilitesrandom.util.ProfileValues;import com.habilitesrandom.api.event.HabilitesRandomEvents;import com.habilitesrandom.network.NetworkSync;import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
/** Checks active forms once per second; daily availability itself is computed lazily from Overworld time. */
public final class PowerfulFormRuntime {private static int ticks;private PowerfulFormRuntime(){}
 public static void register(){ServerTickEvents.END_SERVER_TICK.register(server->{if(++ticks%20!=0)return;long now=System.currentTimeMillis();for(var player:server.getPlayerList().getPlayers()){PlayerProfile p=PlayerDataManager.get(server,player.getUUID());if(p.loadout().powerfulFormActiveUntilMillis()>0&&(!player.isAlive()||p.loadout().powerfulFormActiveUntilMillis()<=now)){var id=ProfileValues.parseId(p.loadout().transformationId());var form=id==null?null:CoreServices.transformations().get(id).orElse(null);PlayerDataManager.update(server,player.getUUID(),PowerfulFormService.finish(p));if(id!=null&&form!=null){var reason=!player.isAlive()?com.habilitesrandom.api.execution.TransformationHooks.EndReason.DEATH:com.habilitesrandom.api.execution.TransformationHooks.EndReason.EXPIRED;CoreServices.executions().transformation(id).ifPresent(h->{try{h.onEnded(player,form,reason);}catch(RuntimeException ignored){}});HabilitesRandomEvents.FORM_ENDED.dispatch(new HabilitesRandomEvents.FormEnded(player,form,reason.name()));}NetworkSync.sendProfile(player);}}});}
 public static long currentDay(net.minecraft.server.MinecraftServer server){var overworld=server.getLevel(net.minecraft.world.level.Level.OVERWORLD);return overworld==null?0:PowerfulFormService.overworldDay(overworld.getOverworldClockTime());}
}
